package io.github.rebrowser.browser;

import static org.junit.Assert.*;
import io.github.rebrowser.browser.BrowserModels.*;
import io.github.rebrowser.bootstrap.ComponentGate;
import java.lang.ref.WeakReference;
import java.lang.reflect.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;

/** Actual catalogs/native window-subscription methods with PRIVATE synthetic allocation only.
 * Does not construct native Android Activity/session/source acceptance or execute a website. */
public final class NativeBrowserWindowModelsTest {
    @Test public void reportedSessionMetadataUpdatesDisplayWithoutCreatingDocumentGeneration(){BrowserCatalogCodecTest.F f=new BrowserCatalogCodecTest.F();WorkspaceRef w=f.add(Level.TEMPORARY);TabRef tab=f.tabs.snapshot(w,f.permit).selected();long generation=f.tabs.currentDocument(tab,f.permit).generation();Selection old=f.tabs.captureSelection(f.permit);assertTrue(f.tabs.updateSessionReportedMetadata(tab,"native title","https://example.test/",f.permit));assertEquals(generation,f.tabs.currentDocument(tab,f.permit).generation());assertEquals("native title",f.tabs.snapshot(w,f.permit).tabs().get(0).title());assertThrows(IllegalStateException.class,()->f.tabs.requireSelection(old,f.permit));}
    @Test public void identicalReportedMetadataDoesNotKeepInvalidatingNativeUiBindings(){BrowserCatalogCodecTest.F f=new BrowserCatalogCodecTest.F();WorkspaceRef w=f.add(Level.TEMPORARY);TabRef tab=f.tabs.snapshot(w,f.permit).selected();f.tabs.updateSessionReportedMetadata(tab,"title","https://example.test/",f.permit);long revision=f.tabs.snapshot(w,f.permit).revision();assertFalse(f.tabs.updateSessionReportedMetadata(tab,"title","https://example.test/",f.permit));assertEquals(revision,f.tabs.snapshot(w,f.permit).revision());}
    @Test public void lateClosedTabReportCannotRetargetReplacement(){BrowserCatalogCodecTest.F f=new BrowserCatalogCodecTest.F();WorkspaceRef w=f.add(Level.TEMPORARY);TabsView before=f.tabs.snapshot(w,f.permit);TabRef old=before.selected();f.tabs.close(old,before.revision(),f.permit);TabRef replacement=f.tabs.snapshot(w,f.permit).selected();assertFalse(f.tabs.updateSessionReportedMetadata(old,"late","https://wrong.test/",f.permit));assertNotSame(old,replacement);assertEquals("",f.tabs.snapshot(w,f.permit).tabs().get(0).displayUrl());}
    @Test public void sourceLockDoesNotPublishSessionMetadata(){BrowserCatalogCodecTest.F f=new BrowserCatalogCodecTest.F();WorkspaceRef w=f.add(Level.TEMPORARY);TabRef tab=f.tabs.snapshot(w,f.permit).selected();f.source.set(ComponentGate.SourceView.untrusted(ComponentGate.SourceState.LOCKED));assertThrows(SecurityException.class,()->f.tabs.updateSessionReportedMetadata(tab,"private","https://example.test/",f.permit));}
    static BrowserHistoryCaptureTest.F observerFixture()throws Exception{BrowserHistoryCaptureTest.F f=new BrowserHistoryCaptureTest.F();f.add(Level.TEMPORARY,"about:blank");f.put("windowObserver",new WeakReference<BrowserCoordinator.NativeWindowObserver>(null));return f;}
    static void signal(BrowserCoordinator domain)throws Exception{Method m=BrowserCoordinator.class.getDeclaredMethod("windowChanged");m.setAccessible(true);m.invoke(domain);}
    @Test public void windowSubscriptionOwnsListenerButProcessDomainOnlyKeepsWeakReference()throws Exception{BrowserHistoryCaptureTest.F f=observerFixture();AtomicInteger count=new AtomicInteger();BrowserCoordinator.NativeWindowObserver listener=count::incrementAndGet;BrowserCoordinator.WindowSubscription subscription=f.domain.observeNativeWindow(listener,f.model.permit);Field field=BrowserCoordinator.class.getDeclaredField("windowObserver");field.setAccessible(true);assertTrue(field.get(f.domain) instanceof WeakReference);signal(f.domain);assertEquals(1,count.get());assertThrows(IllegalStateException.class,()->f.domain.observeNativeWindow(listener,f.model.permit));subscription.close();signal(f.domain);assertEquals(1,count.get());}
    @Test public void closingOldSubscriptionNeverRemovesReplacementWindow()throws Exception{BrowserHistoryCaptureTest.F f=observerFixture();AtomicInteger a=new AtomicInteger(),b=new AtomicInteger();BrowserCoordinator.WindowSubscription old=f.domain.observeNativeWindow(a::incrementAndGet,f.model.permit);old.close();BrowserCoordinator.WindowSubscription next=f.domain.observeNativeWindow(b::incrementAndGet,f.model.permit);old.close();signal(f.domain);assertEquals(0,a.get());assertEquals(1,b.get());next.close();}
    @Test public void sourceLockStillAllowsRetiringOwnPresentationSubscription()throws Exception{BrowserHistoryCaptureTest.F f=observerFixture();BrowserCoordinator.WindowSubscription own=f.domain.observeNativeWindow(()->{},f.model.permit);f.model.source.set(ComponentGate.SourceView.untrusted(ComponentGate.SourceState.LOCKED));own.close();assertThrows(SecurityException.class,()->f.domain.observeNativeWindow(()->{},f.model.permit));}
}
